def main():
 aud={r['sheet']:r for b in json.loads((ROOT/'evidence/sheet_report_number_audit.json').read_text())['workbooks'] if b['file']==SRC for r in b['rows']};dates={r['sheet']:r for b in json.loads((ROOT/'evidence/status_report_date_audit.json').read_text())['workbooks'] if b['file']==SRC for r in b['rows']};wb=load_workbook(ROOT/SRC,read_only=True,data_only=True);items=[]
 for prefix,cells,anchor,en,fa in EVENTS:
  sheet=f'{prefix}-1 DDR Remark';values={c:wb[sheet][c].value for c in cells};assert all(isinstance(v,str) and v.strip() for v in values.values()),(sheet,values);assert anchor.lower() in ' '.join(values.values()).lower(),(sheet,anchor);num=aud[sheet]['header_report_number'];assert num==prefix
  items.append({'sheet':sheet,'worksheet_prefix':prefix,'header_report_number':num,'header_date_unverified':dates[sheet]['report_date_iso_from_header'],'cells':values,'anchor':anchor,'english':en,'persian':fa})
 wb.close();items.sort(key=lambda x:x['header_report_number']);pg=' '.join(PdfReader(ROOT/PROGRAM).pages[6].extract_text().split());assert '91.9 days (Main Plan) + 136.2 days (Contingency Plan)' in pg
 out={'well':'12','source':SRC,'method':'Selected source entries ordered by header number, not a signed chronological reconstruction. Scope, dates and interpretations remain subject to reconciliation.','events':items,'programme':{'file':PROGRAM,'physical_page':7,'text_excerpt':pg,'duration_as_printed':'91.9 days (Main Plan) + 136.2 days (Contingency Plan)'},'limitations':'Selected records do not establish all events, fish status, signed barriers, rig release, actual expenditures or liability.'};(ROOT/'evidence/12_campaign_review.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
 for lang in ('EN','FA'):
  fa=lang=='FA';path=ROOT/f'12_Drilling_Engineering_Report_{lang}.docx';d=Document(path);title='بازسازی منتخب عملیات تعمیر چاه ۱۲' if fa else 'Selected AZNS-12 ST1 workover campaign reconstruction'
  if any(p.text==title for p in d.paragraphs):continue
  anchor=next(p for p in d.paragraphs if p.text in ('Performance and Parameter Analysis','تحلیل عملکرد و پارامترهای عملیاتی'));h=d.add_heading(title,level=2);h.alignment=1;anchor._p.addprevious(h._p)
  p=d.add_paragraph(f'این {len(items)} مدخل منتخب به ترتیب شماره سرصفحه منبع ارائه شده‌اند؛ ترتیب و تاریخ هنوز نیازمند تطبیق با نسخه امضاشده هستند. انتخاب حاضر تمام ساعت‌ها، وضعیت نهایی قطعات یا موانع کنونی را اثبات نمی‌کند.' if fa else f'These {len(items)} selected entries are ordered by source header number; order and dates still require signed-record reconciliation. The selection does not establish every operating hour, final fish disposition or current barriers.');style(p,fa);anchor._p.addprevious(p._p)
  for item in items:
   lead=f"شیت {item['worksheet_prefix']}، شماره سرصفحه {item['header_report_number']} ـ " if fa else f"Worksheet {item['worksheet_prefix']}, header report {item['header_report_number']} — ";cite=f"{SRC}, {item['sheet']}!"+', '.join(item['cells']);p=d.add_paragraph(lead+item['persian' if fa else 'english']+f' [{cite}]');style(p,fa);anchor._p.addprevious(p._p)
  p=d.add_paragraph('صفحه ۷ برنامه عبارت «۹۱٫۹ روز برنامه اصلی + ۱۳۶٫۲ روز برنامه احتیاطی» را چاپ می‌کند. رابطه این دو عدد، مبنای جمع یا جایگزینی و مرز دامنه باید با برنامه مصوب تطبیق شوند؛ این ارقام مدت واقعی یا اضافه‌زمان قراردادی نیستند. [AZNS-012 Workover Program Rev02.pdf، صفحه ۷]' if fa else 'Programme p.7 prints “91.9 days (Main Plan) + 136.2 days (Contingency Plan)”. The relationship of these two values, whether additive or alternative, and the scope boundaries require reconciliation with the approved plan; neither is verified actual duration or contractual overrun. [AZNS-012 Workover Program Rev02.pdf, p.7]');style(p,fa);anchor._p.addprevious(p._p);d.save(path)
 print('Selected events',len(items),'source cells',sum(len(i['cells']) for i in items))
if __name__=='__main__':main()
